module wool_sequence_counter(\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    input [3:0] m,\n    output reg [31:0] result,\n    output reg done\n);\n\n    localparam [1:0] IDLE    = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    localparam [1:0] DONE_ST = 2'd2;\n    \n    localparam [31:0] MOD = 32'd1000000009;\n\n    reg [1:0] state, next_state;\n    reg [31:0] product;\n    reg [3:0] i;\n    reg [31:0] pow2m;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            product <= 32'd1;\n            result <= 32'd0;\n            done <= 1'b0;\n            i <= 4'd0;\n            pow2m <= 32'd0;\n        end else begin\n            state <= next_state;\n            \n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        pow2m <= 32'd1 << m;\n                        product <= 32'd1;\n                        i <= 4'd1;\n                        next_state <= COMPUTE;\n                    end else begin\n                        next_state <= IDLE;\n                    end\n                end\n                \n                COMPUTE: begin\n                    if (i <= n) begin\n                        product <= (product * ((pow2m >= i) ? (pow2m - i) : (MOD - (i - pow2m)))) % MOD;\n                        i <= i + 4'd1;\n                        next_state <= COMPUTE;\n                    end else begin\n                        result <= product;\n                        next_state <= DONE_ST;\n                    end\n                end\n                \n                DONE_ST: begin\n                    done <= 1'b1;\n                    next_state <= IDLE;\n                end\n                \n                default: next_state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule